/**
 * Anonymous client id handling. The X-SangeetPremi-Client-Id header carries a
 * random UUID generated by the extension. It is an IDENTIFIER for rate
 * limiting and usage accounting — it is NOT authentication, grants no access,
 * and is never logged in raw form.
 */
import type { IncomingMessage } from 'node:http';
import { err } from '../http/responses.js';

export const CLIENT_ID_HEADER = 'x-sangeetpremi-client-id';
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export interface ClientIdentity {
  /** Present only when the header was supplied AND well-formed. */
  clientId?: string;
  ip: string;
}

export function extractClientIdentity(req: IncomingMessage): ClientIdentity {
  const raw = req.headers[CLIENT_ID_HEADER];
  const header = Array.isArray(raw) ? raw[0] : raw;
  if (header !== undefined && !UUID_RE.test(header)) {
    throw err.invalidInput(`${CLIENT_ID_HEADER} must be a UUID when provided`);
  }
  return { clientId: header, ip: req.socket.remoteAddress ?? 'unknown' };
}
